\label{convexapprox} Let $E$ be a fully symmetric Banach space on $(0,\infty).$  Suppose $f,g$ are  nonnegative decreasing functions in $E$.  Then $g\in \mathcal Q_E(f)$ if and only if, given $\epsilon>0,$ there exists a nonnegative decreasing function $h\in E$ and an integer $p$ such that $0\le h\le g$  and
\begin{equation}\label{20}
\|g-h\|_E<\epsilon
\end{equation}
and
\begin{equation}\label{21}
\int_{pa}^b h(t)\,dt\le \int_a^b f(t)\,dt, \qquad 0<pa<b<\infty.
\end{equation}

\label{elem}
\begin{equation}\label{11}
\psi_{\kappa}\preceq \psi_{\kappa'}, \qquad \text{ if } \kappa'\le \kappa
\end{equation}
\begin{equation}\label{12}
\psi_{\kappa\wedge\kappa'}\preceq \psi_{\kappa}\vee\psi_{\kappa'}, \qquad \kappa,\kappa'\in \mathcal K.
\end{equation}

\label{technical}  Suppose $\kappa\in\mathcal K$ satisfies
\begin{equation}\label{assumption}
\max(\kappa_n,\kappa_{n+1})=\infty, \qquad n\in\mathbb{Z}.
\end{equation}
Then for any $n\in\mathbb Z$ such that $\kappa_n<\infty$ we have:
\begin{equation}\label{212}
\psi_{\kappa}(t)\ge \frac{9F(a_n)}{25\kappa_na_n} \qquad a_n\le t\le\kappa_na_n.
\end{equation}

We will first prove the Lemma under the additional assumption that \eqref{assumption} holds.
  Since $\|\psi_{{\kappa}^{[r]}}\|_E$ is decreasing in $r$ (by \eqref{11}) it suffices to show that for given $\epsilon>0$ we can find $r$ so that $\|\psi_{{\kappa}^{[r]}}\|_E<\epsilon.$ By Proposition \ref{convexapprox} for any $\epsilon>0$ we can find a nonnegative decreasing function $h\le \psi_{\kappa}$ and an integer $p$ so that
\begin{equation}\label{210}
\int_{pa}^b h(t)\,dt\le \int_a^b f(t)\,dt, \qquad 0<pa<b<\infty,
\end{equation}
and
\begin{equation}\label{211}
\|\psi_{\kappa}-h\|_E<\epsilon/10.
\end{equation}

We shall take $r=36p.$   Let $v=10 (\psi_{\kappa}- h).$  We will show that $\psi_{\kappa^{[r]}}\preceq v.$  In order to do this we must show that if $\kappa_n^{[r]}<\infty$ we have
\begin{equation}\label{need}
F(a_n)\le \int_0^{\kappa_na_n}v^*(t)\,dt.
\end{equation}



If $\kappa_n^{[r]}<\infty$
\begin{align*} \int_0^{\kappa_na_n}v^*(t)\,dt &\ge \int_{pa_n}^{\kappa_na_n}v(t)\,dt\\ &=10 \left(\int_{pa_n}^{\kappa_na_n}\psi_{\kappa}(t)\,dt -\int_{pa_n}^{\kappa_na_n}h(t)\,dt\right)\\
&\ge 10 \left(\int_{pa_n}^{\kappa_na_n}\psi_{\kappa}(t)\,dt -\int_{a_n}^{\kappa_na_n}f(t)\,dt\right),\end{align*} by \eqref{211}.
Hence
by \eqref{212} of Lemma \ref{technical}
\begin{align*} \int_0^{\kappa_na_n}v^*(t)\,dt &\ge 10 \left(\frac{9(\kappa_na_n-pa_n)F(a_n)}{25\kappa_na_n}-\int_{a_n}^{a_{n+1}}f(t)\,dt\right)\\
&\ge 10\left( \frac{35}{36}\frac{9}{25}F(a_n)- \frac{1}4F(a_n)\right)\\
&= F(a_n).\end{align*}




This show that \eqref{need} holds and so $\psi_{\kappa^{[r]}}\preceq v$ and $\|\psi_{\kappa^{[r]}}\|_E<\epsilon.$
This completes the proof when \eqref{assumption} holds.

For the general case let us introduce $\kappa(0)_n=\kappa_n$ if $n$ is even and $\kappa(0)_n=\infty$ if $n$ is odd.  Similarly $\kappa(1)_n=\kappa_n$ if $n$ is odd and $\kappa(1)_n=\infty$ if $n$ is even. Both $\kappa(0)$ and $\kappa(1)$ satisfy \eqref{assumption} Then for an arbitrary $\kappa$ we have
$\kappa^{[r]}=\kappa(0)^{[r]}\wedge \kappa(1)^{[r]}$ and so by \eqref{12},
$$ \limsup_{r\to\infty}\|\psi_{\kappa^{[r]}}\|_E \le \limsup_{r\to\infty}\|\psi_{\kappa(0)^{[r]}}\|_E+\limsup_{r\to\infty}\|\psi_{\kappa(1)^{[r]}}\|_E=0.$$
